const $=id=>document.getElementById(id);let variant='B',crop='full',live=false,engine,revision=0;const state={round:7,firstTime:4,secondTime:9,firstGrowth:65,secondGrowth:40,end:10},initial={...state};
const fields=[['round','現在ラウンド',0,12,1],['firstTime','先攻の残り時',0,12,1],['secondTime','後攻の残り時',0,12,1],['firstGrowth','先攻のそだち',0,100,5],['secondGrowth','後攻のそだち',0,100,5],['end','終了ラウンド',1,12,1]];
async function update(){const request=++revision;$('caption').textContent=variant+'：'+({V16:'現行',A:'現行径・軸修正',B:'有効径＋5%',C:'有効径＋10%'})[variant];document.querySelectorAll('[data-variant]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.variant===variant)));document.querySelectorAll('[data-crop]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.crop===crop)));$('controls').hidden=!live||crop==='stand';$('live').hidden=live||crop==='stand';
if(crop==='stand'||!live){$('display').innerHTML=`<img src="evidence/${variant}-${crop}.jpg" alt="${variant} ${crop}">`;return;}engine??=await import('./clock-v17.mjs');await document.fonts.ready;if(request!==revision)return;$('display').innerHTML=engine.render(state,{variant,crop:crop==='guides'?'full':crop,guides:crop==='guides'});engine.alignNumerals($('display'));}
$('fields').innerHTML=fields.map(([k,label,min,max,step])=>`<label>${label}<input id="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${state[k]}"></label>`).join('');for(const[k,,min,max,step]of fields)$(k).oninput=()=>{const n=Number($(k).value);if(!Number.isInteger(n)||n<min||n>max||(n-min)%step)return;state[k]=n;update();};document.querySelectorAll('[data-variant]').forEach(b=>b.onclick=()=>{variant=b.dataset.variant;update();});document.querySelectorAll('[data-crop]').forEach(b=>b.onclick=()=>{crop=b.dataset.crop;update();});$('live').onclick=()=>{live=true;update();};$('light').onclick=()=>{live=false;update();};$('reset').onclick=()=>{Object.assign(state,initial);for(const[k]of fields)$(k).value=state[k];update();};
